// Etapa 3: peso en gramos, resumen por zona y un intérprete de comandos. Estado global todavía.
const ZONAS = ['CABA', 'Norte', 'Sur', 'Oeste'];
const TRANSICIONES = {
  pendiente: ['en camino', 'cancelado'],
  'en camino': ['entregado', 'demorado'],
  demorado: ['en camino', 'entregado'],
  entregado: [],
  cancelado: [],
};
const envios = [];
let proximoNumero = 1;

const sinTildes = (t) => t.normalize('NFD').replace(/\p{M}/gu, '').toLowerCase();
const kgTexto = (gramos) => (gramos / 1000).toFixed(2).replace('.', ',');

function registrar(destinatario, zona, kgTextoIngresado) {
  const kg = Number(String(kgTextoIngresado).trim().replace(',', '.'));
  const errores = [];
  if (destinatario.trim() === '') errores.push('falta el destinatario');
  if (!ZONAS.includes(zona)) errores.push('zona inválida (' + ZONAS.join(', ') + ')');
  if (!(kg > 0 && kg <= 50)) errores.push('el peso debe estar entre 0 y 50 kg');
  if (errores.length > 0) return 'ERROR: ' + errores.join('; ');
  const id = 'E-' + String(proximoNumero).padStart(4, '0');
  proximoNumero++;
  envios.push({ id, destinatario: destinatario.trim(), zona, gramos: Math.round(kg * 1000), estado: 'pendiente' });
  return 'registrado ' + id;
}

function fila(e) {
  return [e.id, e.destinatario.padEnd(8), e.zona.padEnd(6), kgTexto(e.gramos).padStart(6), e.estado].join('  ');
}

function listar(estado) {
  if (estado !== '' && !(estado in TRANSICIONES)) return 'ERROR: estado desconocido «' + estado + '»';
  const lista = estado === '' ? envios : envios.filter((e) => e.estado === estado);
  return lista.length === 0 ? '(sin envíos)' : lista.map(fila).join('\n');
}

function buscar(texto) {
  const q = sinTildes(texto.trim());
  if (q === '') return 'ERROR: escribí qué buscar';
  const lista = envios.filter((e) => e.id.toLowerCase() === q || sinTildes(e.destinatario).includes(q));
  return lista.length === 0 ? '(sin resultados)' : lista.map(fila).join('\n');
}

function cambiarEstado(id, nuevo) {
  const e = envios.find((x) => x.id === id);
  if (!e) return 'ERROR: no existe ' + id;
  if (!TRANSICIONES[e.estado].includes(nuevo)) {
    const permitidos = TRANSICIONES[e.estado].join(' o ') || 'ninguno';
    return 'ERROR: ' + id + ' no puede pasar de «' + e.estado + '» a «' + nuevo + '» (permitidos: ' + permitidos + ')';
  }
  e.estado = nuevo;
  return id + ' ahora está «' + nuevo + '»';
}

function resumen() {
  const lineas = ['zona'.padEnd(6) + 'envíos'.padStart(8) + 'kg'.padStart(8) + 'entregados'.padStart(12)];
  for (const zona of ZONAS) {
    const deLaZona = envios.filter((e) => e.zona === zona);
    const gramos = deLaZona.reduce((total, e) => total + e.gramos, 0);
    const entregados = deLaZona.filter((e) => e.estado === 'entregado').length;
    const porcentaje = deLaZona.length === 0 ? '-' : Math.round((100 * entregados) / deLaZona.length) + '%';
    lineas.push(zona.padEnd(6) + String(deLaZona.length).padStart(8) + kgTexto(gramos).padStart(8) + porcentaje.padStart(12));
  }
  return lineas.join('\n');
}

function ejecutar(linea) {
  const texto = linea.trim();
  const corte = texto.indexOf(' ');
  const comando = (corte === -1 ? texto : texto.slice(0, corte)).toLowerCase();
  const args = (corte === -1 ? '' : texto.slice(corte + 1)).split('|').map((s) => s.trim());
  if (comando === 'registrar') return registrar(args[0] ?? '', args[1] ?? '', args[2] ?? '');
  if (comando === 'listar') return listar(args[0]);
  if (comando === 'buscar') return buscar(args[0]);
  if (comando === 'estado') return cambiarEstado(args[0], args[1] ?? '');
  if (comando === 'resumen') return resumen();
  return 'ERROR: comando desconocido «' + comando + '» (registrar, listar, buscar, estado, resumen)';
}

