// ===== dominio.mjs =====
// las reglas del negocio. Todo son funciones puras: reciben el estado y devuelven otro.
const ZONAS = ['CABA', 'Norte', 'Sur', 'Oeste'];
const TRANSICIONES = {
  pendiente: ['en camino', 'cancelado'],
  'en camino': ['entregado', 'demorado'],
  demorado: ['en camino', 'entregado'],
  entregado: [],
  cancelado: [],
};

const estadoInicial = () => ({ envios: [], proximo: 1 });
const sinTildes = (t) => t.normalize('NFD').replace(/\p{M}/gu, '').toLowerCase();
function leerKg(texto) {
  const limpio = String(texto).trim();
  if (!/^\d+([.,]\d{1,3})?$/.test(limpio)) return NaN; // solo dígitos, con coma o punto y hasta 3 decimales
  return Number(limpio.replace(',', '.'));
}

function erroresDeAlta({ destinatario, zona, kg }) {
  const errores = [];
  if (destinatario.trim() === '') errores.push('falta el destinatario');
  if (!ZONAS.includes(zona)) errores.push('zona inválida (' + ZONAS.join(', ') + ')');
  if (!(kg >= 0.001 && kg <= 50)) errores.push('el peso debe estar entre 0,001 y 50 kg');
  return errores;
}

function registrar(estado, datos) {
  const errores = erroresDeAlta(datos);
  if (errores.length > 0) return { ok: false, error: errores.join('; ') };
  const envio = {
    id: 'E-' + String(estado.proximo).padStart(4, '0'),
    destinatario: datos.destinatario.trim(),
    zona: datos.zona,
    gramos: Math.round(datos.kg * 1000),
    estado: 'pendiente',
  };
  return { ok: true, estado: { envios: [...estado.envios, envio], proximo: estado.proximo + 1 }, envio };
}

function cambiarEstado(estado, idEscrito, nuevo) {
  const id = idEscrito.trim().toUpperCase();
  const actual = estado.envios.find((e) => e.id === id);
  if (!actual) return { ok: false, error: 'no existe ' + id };
  if (!TRANSICIONES[actual.estado].includes(nuevo)) {
    const permitidos = TRANSICIONES[actual.estado].join(' o ') || 'ninguno';
    return { ok: false, error: id + ' no puede pasar de «' + actual.estado + '» a «' + nuevo + '» (permitidos: ' + permitidos + ')' };
  }
  const envio = { ...actual, estado: nuevo };
  return { ok: true, estado: { ...estado, envios: estado.envios.map((e) => (e.id === id ? envio : e)) }, envio };
}

const filtrarPorEstado = (estado, nombre) => estado.envios.filter((e) => e.estado === nombre);

function buscar(estado, texto) {
  const q = sinTildes(texto.trim());
  return estado.envios.filter((e) => e.id.toLowerCase() === q || sinTildes(e.destinatario).includes(q));
}

function resumenPorZona(estado) {
  return ZONAS.map((zona) => {
    const deLaZona = estado.envios.filter((e) => e.zona === zona);
    const entregados = deLaZona.filter((e) => e.estado === 'entregado').length;
    return {
      zona,
      cantidad: deLaZona.length,
      gramos: deLaZona.reduce((total, e) => total + e.gramos, 0),
      porcentaje: deLaZona.length === 0 ? null : Math.round((100 * entregados) / deLaZona.length),
    };
  });
}

// ===== formato.mjs =====
// convierte datos en texto para la consola. No decide nada del negocio.
const kgTexto = (gramos) => (gramos / 1000).toFixed(2).replace('.', ',');

const filaEnvio = (e) =>
  [e.id, e.destinatario.padEnd(8), e.zona.padEnd(6), kgTexto(e.gramos).padStart(6), e.estado].join('  ');

const tablaEnvios = (lista) => (lista.length === 0 ? '(sin envíos)' : lista.map(filaEnvio).join('\n'));

function tablaResumen(resumen) {
  const cabecera = 'zona'.padEnd(6) + 'envíos'.padStart(8) + 'kg'.padStart(8) + 'entregados'.padStart(12);
  const filas = resumen.map((r) => {
    const pct = r.porcentaje === null ? '-' : r.porcentaje + '%';
    return r.zona.padEnd(6) + String(r.cantidad).padStart(8) + kgTexto(r.gramos).padStart(8) + pct.padStart(12);
  });
  return [cabecera, ...filas].join('\n');
}

// ===== comandos.mjs =====
// traduce una línea de texto a una llamada al dominio. Devuelve { estado, salida }.
const error = (estado, mensaje) => ({ estado, salida: 'ERROR: ' + mensaje });

function ejecutar(estado, linea) {
  const texto = linea.trim();
  if (texto === '') return { estado, salida: '' };
  const corte = texto.indexOf(' ');
  const comando = (corte === -1 ? texto : texto.slice(0, corte)).toLowerCase();
  const args = (corte === -1 ? '' : texto.slice(corte + 1)).split('|').map((s) => s.trim());

  if (comando === 'registrar') {
    const r = registrar(estado, { destinatario: args[0] ?? '', zona: args[1] ?? '', kg: leerKg(args[2] ?? '') });
    return r.ok ? { estado: r.estado, salida: 'registrado ' + r.envio.id } : error(estado, r.error);
  }
  if (comando === 'listar') {
    const filtro = args[0];
    if (filtro !== '' && !(filtro in TRANSICIONES)) return error(estado, 'estado desconocido «' + filtro + '»');
    return { estado, salida: tablaEnvios(filtro === '' ? estado.envios : filtrarPorEstado(estado, filtro)) };
  }
  if (comando === 'buscar') {
    if (args[0] === '') return error(estado, 'escribí qué buscar');
    return { estado, salida: tablaEnvios(buscar(estado, args[0])) };
  }
  if (comando === 'estado') {
    const r = cambiarEstado(estado, args[0], args[1] ?? '');
    return r.ok ? { estado: r.estado, salida: r.envio.id + ' ahora está «' + r.envio.estado + '»' } : error(estado, r.error);
  }
  if (comando === 'resumen') return { estado, salida: tablaResumen(resumenPorZona(estado)) };
  return error(estado, 'comando desconocido «' + comando + '» (registrar, listar, buscar, estado, resumen)');
}

